window.OppositeTeachingData=(()=>{
 const concepts={hard:{id:'hard',name:'Sert',other:'soft',pair:'hardness'},soft:{id:'soft',name:'Yumuşak',other:'hard',pair:'hardness'},wet:{id:'wet',name:'Islak',other:'dry',pair:'moisture'},dry:{id:'dry',name:'Kuru',other:'wet',pair:'moisture'},full:{id:'full',name:'Dolu',other:'empty',pair:'capacity'},empty:{id:'empty',name:'Boş',other:'full',pair:'capacity'},new:{id:'new',name:'Yeni',other:'worn',pair:'condition'},worn:{id:'worn',name:'Eski',other:'new',pair:'condition'},thin:{id:'thin',name:'İnce',other:'thick',pair:'thickness'},thick:{id:'thick',name:'Kalın',other:'thin',pair:'thickness'},day:{id:'day',name:'Gündüz',other:'night',pair:'time'},night:{id:'night',name:'Gece',other:'day',pair:'time'},inside:{id:'inside',name:'İçinde',other:'outside',pair:'position'},outside:{id:'outside',name:'Dışında',other:'inside',pair:'position'},big:{id:'big',name:'Büyük',other:'small',pair:'size'},small:{id:'small',name:'Küçük',other:'big',pair:'size'},heavy:{id:'heavy',name:'Ağır',other:'light',pair:'weight'},light:{id:'light',name:'Hafif',other:'heavy',pair:'weight'},clean:{id:'clean',name:'Temiz',other:'dirty',pair:'cleanliness'},dirty:{id:'dirty',name:'Kirli',other:'clean',pair:'cleanliness'},hot:{id:'hot',name:'Sıcak',other:'cold',pair:'temperature'},cold:{id:'cold',name:'Soğuk',other:'hot',pair:'temperature'}};
 const concept=concepts[new URLSearchParams(location.search).get('concept')]||concepts.clean;
 const color=id=>({...concepts[id===concept.id?id:concept.other],cue:(id===concept.id?concept.name:concepts[concept.other].name)+(concept.pair==='time'?' resmini':' olanı')});
 const colors=[{...color(concept.id),hex:'#4387ab'}];
 const question=concept.pair==='hardness'?'İşaretli nesne sert mi, yumuşak mı? Söyle.':concept.pair==='moisture'?'İşaretli nesne ıslak mı, kuru mu? Söyle.':concept.pair==='capacity'?'Bu kap dolu mu, boş mu? Söyle.':concept.pair==='condition'?'Bu nesne yeni mi, eski mi? Söyle.':concept.pair==='thickness'?'İşaretli nesne ince mi, kalın mı? Söyle.':concept.pair==='time'?'Bu resimde gece mi, gündüz mü? Söyle.':concept.pair==='position'?'İşaretli nesne kabın içinde mi, dışında mı? Söyle.':concept.pair==='size'?'İşaretli nesne büyük mü, küçük mü? Söyle.':concept.pair==='weight'?'İşaretli nesne ağır mı, hafif mi? Söyle.':concept.pair==='cleanliness'?'İşaretli nesne temiz mi, kirli mi? Söyle.':'İşaretli nesne sıcak mı, soğuk mu? Söyle.';
 const defs=[['İki nesne · aynı örnek',2,'object',true],['İki nesne · farklı örnekler',2,'object'],['Günlük ortam · iki seçenek, aynı örnek',2,'scene',true],['Günlük ortam · farklı örnekler',2,'scene'],['Üç nesne arasından',3,'object'],['Dört nesne arasından',4,'object'],['Karışık nesne ve ortamlar · üç seçenek',3,'mixed'],['Karışık nesne ve ortamlar · dört seçenek',4,'mixed'],['Farklı nesneler · iki seçenek',2,'object',false,true],['Farklı nesneler · üç seçenek',3,'scene',false,true],['Farklı nesne ve ortamlar · dört seçenek',4,'mixed',false,true]];
 if(concept.pair==='size'){defs[2][0]='İki gerçek nesne · aynı örnek';defs[3][0]='Farklı renkli gerçek nesneler';defs[6][0]='Karışık gerçek nesneler · üç seçenek';defs[7][0]='Karışık gerçek nesneler · dört seçenek';defs[10][0]='Farklı nesneler · dört seçenek';}
 if(concept.pair==='time')for(const d of defs)d[0]=d[0].replaceAll('nesne','resim');
 const stages=Object.fromEntries(['match','show','name'].map(mode=>[mode,defs.map(([title,count,kind,same,generalize])=>({title,count,kind,same,generalize}))]));
 const item=(id,n,kind,colorId)=>({color:colorId,kind:'concept-object',concept:id,variant:n%5,name:concepts[id].name.toLocaleLowerCase('tr')+' nesne',extent:id==='big'?166:id==='small'?58:176,src:concept.pair==='size'?`./assets/opposites/cleanliness/object-clean-${n%5}.webp`:`./assets/opposites/${concept.pair}/${kind}-${id}-${n%5}${['capacity','condition'].includes(concept.pair)?'-clean-v2':''}.webp`});
 // Position the photographed object, not the white image canvas. Steam stays visible.
 const objectBaselines={capacity:{full:[.91,.896,.95,.925,.945],empty:[.867,.842,.905,.872,.876]},condition:{new:[.783,.909,.864,.909,.934],worn:[.768,.906,.854,.906,.955]},temperature:{cold:[.845,.86,.86,.875,.845],hot:[.99,.985,.985,.985,.985]},cleanliness:{clean:[.86,.94,.91,.90,.85],dirty:[.85,.94,.91,.90,.85]},thickness:{thin:[.91,.91,.91,.85,.86],thick:[.91,.91,.91,.85,.86]}};
 const revisedBaselines={"capacity": {"full": [0.9332, 0.9385, 0.9599, 0.9519, 0.9679], "empty": [0.816, 0.8107, 0.84, 0.8293, 0.832]}, "condition": {"new": [0.8102, 0.8904, 0.861, 0.9144, 0.9251], "worn": [0.7973, 0.8773, 0.8427, 0.9067, 0.9173]}, "hardness": {"hard": [0.8534, 0.8639, 0.856, 0.8298, 0.8639], "soft": [0.8564, 0.8773, 0.8851, 0.8486, 0.8799]}, "moisture": {"wet": [0.8874, 0.9241, 0.8272, 0.9162, 0.9136], "dry": [0.8695, 0.8956, 0.8146, 0.906, 0.906]}};
 const media=x=>{let size=x.extent||176,y=(200-size)/2;const isObject=/\/object-/.test(x.src);const anchors=revisedBaselines[concept.pair]||objectBaselines[concept.pair];if(isObject&&anchors&&concept.pair!=='size'){size=156;const bottom=anchors[x.concept]?.[x.variant];if(bottom)y=174-size*bottom;}
 // Cold tiles contain a faint shadow from the atlas row above, outside the object.
 // Crop only that empty upper strip at render time; keep original pixels and colors.
 const trim=isObject&&concept.pair==='temperature'&&x.concept==='cold'?size*.065:0;
 const image=`<image href="${x.src}" x="${(200-size)/2}" y="${y}" width="${size}" height="${size}" preserveAspectRatio="xMidYMid meet"/>`;
 return `<svg viewBox="0 0 200 200" aria-hidden="true">${trim?`<svg x="0" y="${y+trim}" width="200" height="${200-y-trim}" viewBox="0 ${y+trim} 200 ${200-y-trim}" overflow="hidden">${image}</svg>`:image}</svg>`;};
 function baseCourse(mode,level){const s=stages[mode][level-1];return[{color:concept.id,trials:Array.from({length:5},(_,n)=>{const kind=s.kind==='mixed'?(n%2?'scene':'object'):s.kind,index=s.same?0:n,target=item(concept.id,index,kind,concept.id),options=Array.from({length:s.count-1},(_,i)=>item(concept.other,index+i+(s.count>=3&&n!==level%5?1:0),kind,concept.other+(i+1))),slot=Math.floor(Math.random()*s.count);options.splice(slot,0,target);return{color:concept.id,source:s.generalize?item(concept.id,(index+2)%5,kind,concept.id):{...target},correct:target,options,slot};})}];}
 function course(mode,level){const blocks=baseCourse(mode,level);if(level>=4)for(const block of blocks)for(const trial of block.trials)for(const x of [trial.source,...trial.options]){const filename=x.src.split('/').pop();if(concept.pair==='size')x.src=`./assets/opposites/cleanliness/color-v2/${filename}`;else if(!['weight','thickness','time','position','capacity','condition','hardness','moisture'].includes(concept.pair))x.src=`./assets/opposites/${concept.pair}/color-v2/${filename}`;x.visualColor=(['weight','thickness','time','position','capacity','condition','hardness','moisture'].includes(concept.pair)?['blue','yellow','green','lavender','coral']:concept.pair==='size'?['green','yellow','coral','blue','lavender']:filename.startsWith('scene-')?(concept.pair==='temperature'?['blue','green','yellow','lavender','coral']:['blue','yellow','green','yellow','blue']):(concept.pair==='temperature'?['blue','green','yellow','coral','lavender']:['green','yellow','coral','blue','lavender']))[x.variant];if(concept.pair==='hardness')x.visualColor=['yellow','blue','gray','red','purple'][x.variant];if(concept.pair==='moisture')x.visualColor=['blue','red','yellow','green','brown'][x.variant];}return blocks;}
 const nextStep=(mode,c,level)=>level<stages[mode].length?{color:concept.id,level:level+1,block:0}:null;
 function judge(text){if(window.NamingRules.hasInappropriate(text))return'inappropriate';const words=window.NamingRules.normalize(text).split(' ').filter(w=>!['bu','bir','nesne','olan','resim'].includes(w)),expected=window.NamingRules.normalize(concept.name);return!words.length?'uncertain':words.every(w=>w===expected)?'correct':'wrong';}
 function correction(c,text,kind,retry=true){const safe=window.NamingRules.safeText(text).replace(/[.!?;:"“”]/g,'').trim();return(kind==='inappropriate'?'Bu söylediğin sözcük uygun bir sözcük değil. ':safe?`Hayır, bu ${safe} değil. `:'')+`Bu ${concept.name.toLocaleLowerCase('tr')}.`+(retry?' Şimdi sen söyle.':'');}
 const explanation=x=>({hard:'Bastırılınca biçimi değişmiyor.',soft:'Bastırılınca eziliyor, biçimi değişiyor.',wet:'Üzerinde su var. Su damlaları görünüyor.',dry:'Üzerinde su yok. Kuru.',full:'Kabın içi dolu.',empty:'Kabın içinde bir şey yok.',new:'Henüz kullanılmamış. Yıpranma izi yok.',worn:'Kullanılmış ve yıpranmış. Üzerinde aşınma izleri var.',thin:'Kalınlığı daha az.',thick:'Kalınlığı daha fazla.',day:'Güneş gökyüzünde. Ortalık aydınlık.',night:'Ay ve yıldızlar görünüyor. Gökyüzü karanlık.',inside:'İşaretli nesne kabın içinde.',outside:'İşaretli nesne kabın dışında.',clean:'Üzerinde kir yok.',dirty:'Üzerinde kir var.',hot:'Buhar çıkıyor.',cold:'İçinde buz var.',big:'Diğer nesnelere göre daha büyük.',small:'Diğer nesnelere göre daha küçük.',heavy:'İşaretli nesnenin tartı kefesi aşağıda. Daha ağır.',light:'İşaretli nesnenin tartı kefesi yukarıda. Daha hafif.'}[x.concept]);
 const instruction=mode=>color(concept.id).cue+' '+(mode==='match'?'eşle':'göster')+'.';
 return{instruction,concept,colors,color,question,stages,course,nextStep,media,judge,correction,explanation};
})();
